
/**
 * Purpose: Display real student learning profiles from FastAPI.
 *
 * Original implementation: Existing team project code.
 * AI-assisted modification: Replace mock student profiles with
 * SQLite-backed student profiles and preferences.
 *
 * Directed by: Edenna Chen
 * Generated by: ChatGPT (OpenAI), GPT-6, 2026-11-05
 * Human edits: Pending review
 * External sources: None
 *
 * Notes:
 * - Loads profiles from /api/students/{id}/profile.
 * - Preserves the existing two-column layout.
 * - Does not fabricate mastery scores.
 * - Teacher notes are displayed without being overwritten.
 */

import { useEffect, useState } from 'react';
import type { ApiStudent } from '../../api/students';

type StudentProfile = {
  student?: Record<string, unknown>;
  preferences?: Record<string, unknown>;
  sections?: unknown;
  teacher_notes?: unknown;
};

type StudentsProps = {
  students: ApiStudent[];
  selectedStudentId: string | null;
  onCreateLesson: (studentId: string) => void;
};

function displayValue(value: unknown): string {
  if (value === null || value === undefined || value === '') {
    return 'Not specified';
  }

  if (Array.isArray(value)) {
    return value.length ? value.map(String).join(', ') : 'Not specified';
  }

  if (typeof value === 'boolean') {
    return value ? 'Yes' : 'No';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

export default function Students({
  students,
  selectedStudentId,
  onCreateLesson,
}: StudentsProps) {
  const [selected, setSelected] = useState(
    selectedStudentId ?? students[0]?.id ?? ''
  );

  const [profile, setProfile] = useState<StudentProfile | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (
      selectedStudentId &&
      students.some(student => student.id === selectedStudentId)
    ) {
      setSelected(selectedStudentId);
    }
  }, [selectedStudentId, students]);

  useEffect(() => {
    if (!selected && students.length > 0) {
      setSelected(students[0].id);
    }
  }, [selected, students]);

  useEffect(() => {
    if (!selected) return;

    const controller = new AbortController();

    async function loadProfile() {
      setLoading(true);
      setError(null);
      setProfile(null);

      try {
        const response = await fetch(
          `/api/students/${encodeURIComponent(selected)}/profile`,
          { signal: controller.signal }
        );

        if (!response.ok) {
          throw new Error(`HTTP ${response.status}`);
        }

        const data: StudentProfile = await response.json();

        if (!controller.signal.aborted) {
          setProfile(data);
        }
      } catch (err) {
        if (!controller.signal.aborted) {
          setError(
            err instanceof Error ? err.message : 'Unable to load profile'
          );
        }
      } finally {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      }
    }

    void loadProfile();

    return () => controller.abort();
  }, [selected]);

  const student = students.find(s => s.id === selected);

  return (
    <div className="page">
      <p className="eyebrow">CLASSROOM</p>
      <h1>Student profiles</h1>
      <p className="lead">
        Review learning preferences, teacher notes, and lesson planning.
      </p>

      <div className="two-col student-layout">
        <div className="card">
          <h3>Students</h3>

          {students.map(s => (
            <button
              type="button"
              className={
                'student-select ' + (selected === s.id ? 'chosen' : '')
              }
              key={s.id}
              onClick={() => setSelected(s.id)}
            >
              {s.name}
            </button>
          ))}
        </div>

        <div className="card">
          {!student && <p className="muted">Select a student.</p>}

          {student && (
            <>
              <p className="eyebrow">STUDENT PROFILE</p>
              <h2>{student.name}</h2>

              <p className="muted small">
                {student.grade_level !== null
                  ? `Grade ${student.grade_level}`
                  : 'Grade not specified'}
              </p>

              <button
                type="button"
                className="btn primary"
                onClick={() => onCreateLesson(student.id)}
              >
                + Create Lesson
              </button>

              <div className="detail-row">
                <strong>Current lesson</strong>
                <span className="muted">Not assigned yet</span>
              </div>

              {loading && <p className="muted">Loading profile...</p>}

              {error && (
                <p role="alert">
                  Unable to load student profile: {error}
                </p>
              )}

              {profile && !loading && (
                <>
                  <h3>Learning preferences</h3>

                  {profile.preferences &&
                    Object.entries(profile.preferences).map(
                      ([key, value]) => (
                        <div className="detail-row" key={key}>
                          <strong>
                            {key.replaceAll('_', ' ')}
                          </strong>
                          <span>{displayValue(value)}</span>
                        </div>
                      )
                    )}

                  <h3 style={{ marginTop: 24 }}>Learning profile</h3>

                  {profile.sections ? (
                    <pre style={{
                      whiteSpace: 'pre-wrap',
                      overflowWrap: 'anywhere',
                      fontFamily: 'inherit',
                      fontSize: '0.9rem',
                    }}>
                      {JSON.stringify(profile.sections, null, 2)}
                    </pre>
                  ) : (
                    <p className="muted">
                      No profile sections available.
                    </p>
                  )}

                  <h3 style={{ marginTop: 24 }}>Teacher notes</h3>

                  {profile.teacher_notes ? (
                    <pre style={{
                      whiteSpace: 'pre-wrap',
                      overflowWrap: 'anywhere',
                      fontFamily: 'inherit',
                      fontSize: '0.9rem',
                    }}>
                      {JSON.stringify(profile.teacher_notes, null, 2)}
                    </pre>
                  ) : (
                    <p className="muted">
                      No teacher notes returned.
                    </p>
                  )}

                  <h3 style={{ marginTop: 24 }}>
                    Competency mastery
                  </h3>
                  <p className="muted">
                    No verified competency results displayed yet.
                  </p>

                  <h3>Recent lesson observations</h3>
                  <p className="muted">
                    Lesson observations will appear after
                    student activities are recorded.
                  </p>
                </>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}
